// Validate batch envelope. Edge cases: missing batch_id, records not an array, empty batch, oversized batch.
const body = $input.first().json.body || {};
const errors = [];
if (!body.batch_id || typeof body.batch_id !== 'string' || body.batch_id.trim() === '') errors.push('batch_id is required');
if (!Array.isArray(body.records)) {
  errors.push('records must be an array');
} else {
  if (body.records.length === 0) errors.push('records array must not be empty');
  if (body.records.length > 500) errors.push('records array exceeds 500-item batch limit; split into multiple batches');
}
if (errors.length) return [{ json: { valid: false, errors } }];
return [{ json: { valid: true, batch_id: body.batch_id.trim(), source: body.source || 'unknown', records: body.records } }];

// Flag duplicate record ids within the batch before any per-record processing. First occurrence wins, later ones are flagged rather than silently overwriting each other downstream.
const t = $json;
const seen = new Set();
const records = (t.records || []).map((r, idx) => {
  const key = r && r.id !== undefined && r.id !== null ? String(r.id) : null;
  let is_duplicate = false;
  if (key !== null) {
    if (seen.has(key)) is_duplicate = true; else seen.add(key);
  }
  return { ...r, _row_index: idx, _duplicate: is_duplicate };
});
return [{ json: { batch_id: t.batch_id, source: t.source, records } }];

// Fan the batch out into one item per record, carrying batch context along with each one.
const t = $json;
return (t.records || []).map(r => ({ json: { ...r, batch_id: t.batch_id, source: t.source } }));

// Hand-rolled schema check for one record.
// Expected shape: { id: string, email: string, amount: number>=0, currency?: 3-letter code, created_at: ISO-ish date string }
const r = $json;
const errors = [];
const recordId = (r.id !== undefined && r.id !== null) ? String(r.id) : `row_${r._row_index}`;

if (r._duplicate) errors.push('duplicate id within batch');
if (r.id === undefined || r.id === null || String(r.id).trim() === '') errors.push('id is required');
if (!r.email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(r.email)) errors.push('email must be a valid email address');
if (typeof r.amount !== 'number' || isNaN(r.amount) || r.amount < 0) errors.push('amount must be a non-negative number');
if (r.currency !== undefined && !/^[A-Z]{3}$/.test(r.currency)) errors.push('currency must be a 3-letter uppercase code if provided');
if (!r.created_at || typeof r.created_at !== 'string') errors.push('created_at is required and must be a string');

return [{ json: { valid: errors.length === 0, errors, record_id: recordId, record: r, batch_id: r.batch_id, source: r.source } }];

// Normalize the record. Edge case: an unparseable created_at must not throw and kill the item -- it becomes a typed transform failure instead.
const t = $json;
const r = t.record;
try {
  const parsedDate = new Date(r.created_at);
  if (isNaN(parsedDate.getTime())) throw new Error(`unparseable created_at value: ${r.created_at}`);
  const transformed = {
    id: String(r.id).trim(),
    email: r.email.trim().toLowerCase(),
    amount: Math.round(r.amount * 100) / 100,
    currency: (r.currency || 'USD').toUpperCase(),
    created_at: parsedDate.toISOString()
  };
  return [{ json: { transform_ok: true, record_id: t.record_id, transformed, batch_id: t.batch_id } }];
} catch (e) {
  return [{ json: { transform_ok: false, record_id: t.record_id, transform_error: e.message, record: r, batch_id: t.batch_id } }];
}

const items = $json.results || [];
const counts = { total: items.length, loaded: 0, invalid: 0, load_failed: 0, skipped: 0 };
for (const r of items) {
  if (r.status === 'loaded') counts.loaded++;
  else if (r.status === 'invalid') counts.invalid++;
  else if (r.status === 'load_failed') counts.load_failed++;
  else if (r.status === 'skipped') counts.skipped++;
}
return [{ json: { batch_id: items[0]?.batch_id, counts, results: items } }];
